const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
const errorPage = message => `<!doctype html><html lang="hu"><head><meta charset="utf-8"><title>Hiba – YouTube meta</title><style>body{font:16px system-ui;max-width:650px;margin:48px auto;padding:0 20px;color:#222}.error{border-left:4px solid #b00020;padding:12px 16px;background:#fff4f4;white-space:pre-wrap}</style></head><body><h1>Nem sikerült megnyitni az űrlapot</h1><p class="error">${esc(message)}</p><p>Javítsd a jelzett hibát, majd töltsd újra az oldalt. Ha a hiba megmarad, küldd el ezt az üzenetet az üzemeltetőnek.</p></body></html>`;
try {
  if ($json.error) throw new Error($json.error.message ?? String($json.error));
  const result = JSON.parse($json.stdout ?? '{}');
  if (!result.ok) return [{json:{html:errorPage(result.error?.message ?? 'Ismeretlen hiba történt az űrlap adatainak betöltésekor.')}}];
  if (!Array.isArray(result.channels) || !Array.isArray(result.folders)) throw new Error('Az űrlap adatainak formátuma hibás: channels és folders listát vártam.');
  const {channels, folders} = result;
  const webhookUrl = $('Űrlap megnyitása').first().json.webhookUrl;
  if (!webhookUrl) throw new Error('Nem érkezett meg a webhook URL-je; az űrlap beküldési címe nem állítható össze.');
  const action = webhookUrl.replace(/youtube-meta$/, 'youtube-meta-submit');
  const channelOptions = channels.map(c => `<option value="${esc(c.key)}"${channels.length === 1 ? ' selected' : ''}>${esc(c.displayName)}</option>`).join('');
  const folderOptions = folders.map(name => `<option value="${esc(name)}"${folders.length === 1 ? ' selected' : ''}>${esc(name)}</option>`).join('');
  const initialSelectionComplete = channels.length === 1 && folders.length === 1;
  const html = `<!doctype html>
<html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>YouTube meta</title>
<style>body{font:16px system-ui;max-width:560px;margin:48px auto;padding:0 20px}select{display:block;width:100%;padding:12px;margin:8px 0 20px}button{padding:12px 24px}</style></head>
<body><h1>YouTube meta</h1>
<form method="post" action="${esc(action)}">
<label for="channelKey">Csatorna</label><select id="channelKey" name="channelKey" required><option value="">Válassz csatornát</option>${channelOptions}</select>
<label for="videoFolder">Videómappa</label><select id="videoFolder" name="videoFolder" required><option value="">Válassz mappát</option>${folderOptions}</select>
<button id="next" type="submit"${initialSelectionComplete ? '' : ' disabled'}>Tovább</button></form>
<script>const c=document.querySelector('#channelKey'),f=document.querySelector('#videoFolder'),b=document.querySelector('#next');function update(){b.disabled=!(c.value&&f.value)}c.addEventListener('change',update);f.addEventListener('change',update);update();</script>
</body></html>`;
  return [{json:{html}}];
} catch (error) {
  return [{json:{html:errorPage(error?.message ?? String(error))}}];
}

try {
const body = $('Kiválasztás fogadása').first().json.body ?? {};
const channelKey = typeof body.channelKey === "string" ? body.channelKey.trim() : "";
const videoFolder = typeof body.videoFolder === "string" ? body.videoFolder.trim() : "";
const problems = [];
if (!channelKey) problems.push("Nem érkezett csatornaválasztás.");
if (!videoFolder) problems.push("Nem érkezett videómappa-választás.");
if (videoFolder === "." || videoFolder === ".." || videoFolder.includes("/") || videoFolder.includes("\\")) problems.push("A videómappa neve érvénytelen; csak egy közvetlen mappanév adható meg.");
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
if (problems.length) {
  const message = problems.join(" ");
  const html = `<!doctype html><html lang="hu"><meta charset="utf-8"><title>Hiba a beküldésnél</title><body><h1>Nem sikerült rögzíteni a választást</h1><p>${esc(message)}</p><p>Menj vissza az űrlapra, javítsd a választást, majd küldd be újra.</p></body></html>`;
  return [{json:{ok:false,error:{stage:"űrlap beküldésének ellenőrzése",message},html}}];
}
if ($json.error) throw new Error($json.error.message ?? String($json.error));
const sourceResult = JSON.parse($json.stdout ?? '{}');
if (!sourceResult.ok || sourceResult.missingFiles?.length) throw new Error(sourceResult.error?.message ?? 'A csatornaforrások nem tölthetők be.');
const styleFile = sourceResult.files.find(file => file.path.endsWith('/style.md'));
if (!styleFile) throw new Error('A kiválasztott csatornához nem található style.md.');
const openingMatch = styleFile.content.match(/^### Első kérdés\s*\r?\n([\s\S]*?)(?=^###? |^## |\s*$)/m);
const openingMessage = openingMatch?.[1].trim().split(/\r?\n/)[0];
if (!openingMessage) throw new Error('A style.md nem tartalmaz kitöltött „Nyitó kérdés” részt.');
const webhookUrl = String($('Kiválasztás fogadása').first().json.webhookUrl ?? '');
const origin = webhookUrl.split('/webhook/')[0];
if (!origin) throw new Error('Nem állítható össze a chat webcíme.');
const chatUrl = `${origin}/webhook/c50219e8-5cba-4cf9-a77f-9c5908890b4f/chat`;
const jsonForScript = value => JSON.stringify(value).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/&/g, '\\u0026');
const metadata = jsonForScript({channelKey,videoFolder});
const openingMessageJson = jsonForScript(openingMessage);
const widgetUrl = jsonForScript(chatUrl);
const sessionId = jsonForScript(`youtube-meta-${channelKey}-${videoFolder}-${Date.now()}`);
const html = `<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YouTube metaadat-chat</title>
<style>
*{box-sizing:border-box}html,body{height:100%;margin:0;font:16px system-ui,sans-serif;color:#222;background:#f5f6f8}body{min-height:100dvh}.chat{height:100dvh;max-width:900px;margin:0 auto;background:white;display:flex;flex-direction:column}.header{padding:16px 20px;border-bottom:1px solid #ddd}.header h1{font-size:20px;margin:0 0 4px}.header p{margin:0;color:#666;font-size:14px}.messages{flex:1;overflow:auto;padding:20px;display:flex;flex-direction:column;gap:12px}.message{max-width:min(80%,680px);padding:12px 16px;border-radius:14px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.45}.bot{background:#f0f1f4;align-self:flex-start}.user{background:#2459d3;color:#fff;align-self:flex-end}.composer{border-top:1px solid #ddd;padding:12px 16px;display:flex;gap:10px;align-items:flex-end}.composer textarea{flex:1;resize:vertical;min-height:48px;max-height:180px;padding:12px;border:1px solid #aaa;border-radius:8px;font:inherit}.composer button{padding:12px 20px;border:0;border-radius:8px;background:#2459d3;color:white;font:inherit;cursor:pointer}.composer button:disabled{opacity:.55;cursor:wait}.status{min-height:20px;padding:0 16px 8px;color:#8a1c1c;font-size:14px}@media(max-width:600px){.header{padding:12px}.messages{padding:14px}.composer{padding:10px}.composer button{padding:12px}}
</style></head><body><main class="chat"><header class="header"><h1>YouTube metaadat-chat</h1><p>DeepSeek Chat · ${String(channelKey).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))} / ${String(videoFolder).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</p></header><section id="messages" class="messages" role="log" aria-live="polite"></section><div id="status" class="status" role="alert"></div><form id="composer" class="composer"><textarea id="chat-input" data-test-id="chat-input" aria-label="Üzenet" placeholder="Írd be az üzeneted..." rows="2" required></textarea><button id="send" type="submit">Küldés</button></form></main>
<script>
const webhookUrl=${widgetUrl},metadata=${metadata},sessionId=${sessionId};
const messages=document.querySelector('#messages'),form=document.querySelector('#composer'),input=document.querySelector('#chat-input'),button=document.querySelector('#send'),status=document.querySelector('#status');
function addMessage(kind,text){const el=document.createElement('div');el.className='message '+kind;el.textContent=text;messages.appendChild(el);messages.scrollTop=messages.scrollHeight}
addMessage('bot',${openingMessageJson});
form.addEventListener('submit',async event=>{event.preventDefault();const chatInput=input.value.trim();if(!chatInput)return;addMessage('user',chatInput);input.value='';input.focus();button.disabled=true;status.textContent='Válasz betöltése…';try{const response=await fetch(webhookUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'sendMessage',sessionId,chatInput,metadata})});let data;try{data=await response.json()}catch{throw new Error('A szerver nem olvasható választ küldött (HTTP '+response.status+').')}if(!response.ok||data.type==='error')throw new Error(data.output||data.message||data.error||('HTTP '+response.status));if(typeof data.output!=='string'||!data.output.trim())throw new Error('A workflow üres választ adott.');addMessage('bot',data.output);status.textContent=''}catch(error){addMessage('bot','A chat feldolgozása nem sikerült. Próbáld újra később.');status.textContent='Nem érkezett válasz.'}finally{button.disabled=false;input.focus()}});
input.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();form.requestSubmit()}});
</script></body></html>`;
return [{json:{ok:true,channelKey,videoFolder,chatUrl,html}}];
} catch (error) {
  const message = 'Nem sikerült előkészíteni a chatet. Ellenőrizd a kiválasztást, majd próbáld újra.';
  const html = `<!doctype html><html lang="hu"><meta charset="utf-8"><title>Hiba a chat indításakor</title><body><h1>Nem sikerült elindítani a chatet</h1><p role="alert">${message}</p><p>Próbáld újra később.</p></body></html>`;
  return [{json:{ok:false,error:{stage:"chat inicializálása"},html}}];
}

const trigger = $('Metaadat-chat').first().json;
const metadata = trigger.metadata ?? {};
const channelKey = String(metadata.channelKey ?? '');
const videoFolder = String(metadata.videoFolder ?? '');
try {
  if ($json.error) throw new Error($json.error.message ?? String($json.error));
  const result = JSON.parse($json.stdout ?? '{}');
  if (!result.ok || !Array.isArray(result.files)) throw new Error(result.error?.message ?? 'A csatorna-forrásfájlok betöltése nem sikerült.');
  if (!channelKey || !videoFolder) throw new Error('A chatből hiányzik a kiválasztott csatorna vagy videómappa.');
  if (channelKey !== result.channelKey) throw new Error('A betöltött csatorna nem egyezik a chat választásával.');
  if (result.missingFiles?.length) throw new Error(`Hiányzó registry fájlok: ${result.missingFiles.join(', ')}`);
  const loadedFiles = result.files.map(file => `## ${file.path}\n${file.content}`).join('\n\n');
  const sourceContext = `Kiválasztott csatornakulcs: ${channelKey}\nKiválasztott videómappa: ${videoFolder}\n\nBetöltött fájlok (${result.files.length}):\n\n${loadedFiles}`;
  return [{json:{ok:true,chatInput:trigger.chatInput,sessionId:trigger.sessionId,channelKey,videoFolder,sourceContext}}];
} catch (error) {
  return [{json:{ok:false,output:'A csatorna forrásai nem tölthetők be, ezért a chat jelenleg nem tud válaszolni.',error:{stage:'channel context loading',detail:error?.message ?? String(error)}}}];
}

const error = $json.error;
if (error) return [{json:{output:'A chat feldolgozása nem sikerült. Próbáld újra később.'}}];
const answer = $json.output ?? $json.text;
if (typeof answer !== 'string' || !answer.trim()) return [{json:{output:'A chat nem adott választ. Próbáld újra később.'}}];
return [{json:{output:answer}}];
